import os, sys, torch
os.environ["TORCH_EXTENSIONS_DIR"]="/tmp/wmma_ext"
from torch.utils.cpp_extension import load_inline

cuda_src = r'''
#include <cuda_fp16.h>
#include <mma.h>
#include <cuda.h>
using namespace nvcuda;

// Co-batched W=V^T A then YT=T^T W, warp-per-matrix WMMA tf32.
// Grid (col_tiles, ceil(B/MB)). Block = MB warps. Warp w -> matrix g*MB+w.
// V: (B,BLK,N) row-major; A: (B,N,N); T: (B,BLK,BLK); YT out: (B,BLK,N).
// BLK=32. BNc tile width (16). Output W tile (32, BNc). K=pheight.
template<int MB, int BNc>
__global__ void cobatch_w(
    const float* __restrict__ A, const float* __restrict__ V,
    const float* __restrict__ T, float* __restrict__ YT,
    int B, int N, int j, int pheight, int ncols, int jb,
    long sab, long san, long svb, long svk, long svn,
    long stb, long stk, long stn, long syb, long syk, long syn)
{
    const int warp = threadIdx.x >> 5;
    const int lane = threadIdx.x & 31;
    const int col_tile = blockIdx.x;
    const int mid = blockIdx.y * MB + warp;
    const int c0 = col_tile * BNc;
    const int BLK = 32;
    if (mid >= B) return;

    const float* Ab = A + (long)mid*sab + (long)j*san + jb;   // (pheight, ncols) view, row r col c -> [r*san + c]
    const float* Vb = V + (long)mid*svb;                       // (BLK, pheight): [k*svk + r*svn]
    const float* Tb = T + (long)mid*stb;
    float* YTb = YT + (long)mid*syb + (long)c0*syn;            // store (BLK, BNc): [k*syk + c*syn]

    // Accumulator: W is (32, BNc). With BNc=16: two 16x16 tiles (M0, M1).
    wmma::fragment<wmma::accumulator, 16, 16, 8, float> accW0, accW1;
    wmma::fill_fragment(accW0, 0.0f);
    wmma::fill_fragment(accW1, 0.0f);

    // smem staging per warp: A tile (16 rows x BNc) and V tile (32 x 16) per k-step
    // We loop K in steps of 8 (tf32 wmma K=8). Load straight from global into fragments.
    // V^T: we need V[k_blk (BLK), r (K)] as the LHS A-fragment? W[blk,c]=sum_r V[blk,r]*A[r,c].
    // So matrix-mul: W(M=BLK, N=BNc) = Vrow(M=BLK,K=pheight) * A(K=pheight, N=BNc).
    // LHS = Vrow (row-major MxK): Vrow[blk, r] = Vb[blk*svk + r*svn].
    // RHS = A (row-major KxN): A[r,c] = Ab[r*san + c].
    for (int k0 = 0; k0 < pheight; k0 += 8) {
        // load A fragment (8 rows x BNc) row-major, B-matrix layout
        wmma::fragment<wmma::matrix_b, 16, 16, 8, wmma::precision::tf32, wmma::row_major> fragA;
        // load V fragments for M0 (rows 0..15) and M1 (rows 16..31), A-matrix layout (MxK)
        wmma::fragment<wmma::matrix_a, 16, 16, 8, wmma::precision::tf32, wmma::row_major> fragV0, fragV1;
        // Need pointers; wmma::load_matrix_sync loads 16x8 (or 16xBNc). Strides in elements.
        // A: KxN tile at rows [k0,k0+8), cols [c0,c0+BNc); ld = san.
        wmma::load_matrix_sync(fragA, Ab + (long)k0*san + c0, san);
        wmma::load_matrix_sync(fragV0, Vb + 0*svk + (long)k0*svn, svk); // WRONG stride? Vrow is MxK: M index=blk along svk, K index=r along svn
        wmma::load_matrix_sync(fragV1, Vb + 16*svk + (long)k0*svn, svk);
        // tf32 requires rounding the fragment elements
        #pragma unroll
        for (int t=0;t<fragV0.num_elements;t++){ fragV0.x[t]=wmma::__float_to_tf32(fragV0.x[t]); }
        #pragma unroll
        for (int t=0;t<fragV1.num_elements;t++){ fragV1.x[t]=wmma::__float_to_tf32(fragV1.x[t]); }
        #pragma unroll
        for (int t=0;t<fragA.num_elements;t++){ fragA.x[t]=wmma::__float_to_tf32(fragA.x[t]); }
        wmma::mma_sync(accW0, fragV0, fragA, accW0);
        wmma::mma_sync(accW1, fragV1, fragA, accW1);
    }
    // store W to smem to do YT=T^T W (small, do simple). Put W (32,BNc) in smem per warp.
    extern __shared__ float smem[];
    float* sW = smem + warp * (BLK*BNc);
    wmma::store_matrix_sync(sW + 0,       accW0, BNc, wmma::mem_row_major);
    wmma::store_matrix_sync(sW + 16*BNc,  accW1, BNc, wmma::mem_row_major);
    __syncwarp();
    // YT[i,c] = sum_k T[k,i]*W[k,c]  (T is (BLK,BLK)). Each lane handles some (i,c).
    // 32 lanes, BLK*BNc = 32*16 = 512 outputs -> 16 per lane. Simple serial.
    for (int idx = lane; idx < BLK*BNc; idx += 32) {
        int i = idx / BNc; int c = idx % BNc;
        float acc = 0.0f;
        #pragma unroll
        for (int k=0;k<BLK;k++) acc += Tb[k*stk + i*stn] * sW[k*BNc + c];
        if (c0 + c < ncols) YTb[i*syk + c*syn] = acc;
    }
}

extern "C" __global__ void cobatch_w_4_16(
    const float* A, const float* V, const float* T, float* YT,
    int B,int N,int j,int pheight,int ncols,int jb,
    long sab,long san,long svb,long svk,long svn,long stb,long stk,long stn,long syb,long syk,long syn){
    cobatch_w<4,16>(A,V,T,YT,B,N,j,pheight,ncols,jb,sab,san,svb,svk,svn,stb,stk,stn,syb,syk,syn);
}
'''

