// ---------------------------------------------------------------------------
// qr_cobatch_w: CO-BATCHED W-reduction. Warp-per-matrix WMMA tf32.
//
// The trailing W = V^T @ A_trail reduction over a tiny (BLK=32, BNc) output but
// deep K=pheight is PARALLELISM-starved when one CTA does ONE matrix: only a few
// warps busy, the rest idle (measured 0.74 eligible warps/scheduler, 51% no-
// eligible-warp). At n=512 there are B=640 INDEPENDENT matrices. This kernel
// co-batches MB matrices into ONE block: warp w computes matrix (g*MB+w)'s W
// tile via WMMA fragments, so each scheduler gets MB matrices' independent MMA
// chains to interleave -> fills the idle warps.
//
// Layout: V (B,BLK,pheight)-strided [k*svk + r*svn], svn=1 (K contiguous);
//   A_trail row r col c -> Ab[r*san + c], c contiguous; T (B,BLK,BLK);
//   output YT (B,BLK,N)-strided so the existing Triton apply kernel consumes it.
// W(M=BLK, N=BNc) = Vrow(M=BLK, K=pheight) @ A(K=pheight, N=BNc).
//   LHS Vrow is matrix_a row_major (M along svk, K along svn==1).
//   RHS A    is matrix_b row_major (K along san,  N along 1).
// BLK=32 => two M-tiles (rows 0..15, 16..31). BNc in {16,32}.
// ---------------------------------------------------------------------------
using namespace nvcuda;

template<int MB, int BNc>
__device__ __forceinline__ void cobatch_w_impl(
    const float* __restrict__ A, const float* __restrict__ V,
    const float* __restrict__ T, float* __restrict__ YT,
    int B, int N, int j, int pheight, int ncols, int jb,
    long sab, long san, long svb, long svk, long svn,
    long stb, long stk, long stn, long syb, long syk, long syn)
{
    const int warp = threadIdx.x >> 5;
    const int lane = threadIdx.x & 31;
    const int col_tile = blockIdx.x;
    const int mid = blockIdx.y * MB + warp;
    const int c0 = col_tile * BNc;
    const int BLK = 32;
    const int NT = BNc / 16;                 // # of 16-wide N-subtiles
    if (mid >= B) return;

    const float* Ab = A + (long)mid * sab + (long)j * san + jb;
    const float* Vb = V + (long)mid * svb;
    const float* Tb = T + (long)mid * stb;
    float* YTb = YT + (long)mid * syb + (long)c0 * syn;

    // accumulators: 2 M-tiles x NT N-tiles
    wmma::fragment<wmma::accumulator, 16, 16, 8, float> acc[2][BNc / 16];
    #pragma unroll
    for (int m = 0; m < 2; ++m)
        #pragma unroll
        for (int t = 0; t < NT; ++t) wmma::fill_fragment(acc[m][t], 0.0f);

    for (int k0 = 0; k0 < pheight; k0 += 8) {
        wmma::fragment<wmma::matrix_a, 16, 16, 8, wmma::precision::tf32, wmma::row_major> fragV0, fragV1;
        wmma::load_matrix_sync(fragV0, Vb + 0  * svk + (long)k0 * svn, svk);
        wmma::load_matrix_sync(fragV1, Vb + 16 * svk + (long)k0 * svn, svk);
        #pragma unroll
        for (int t = 0; t < fragV0.num_elements; ++t) fragV0.x[t] = wmma::__float_to_tf32(fragV0.x[t]);
        #pragma unroll
        for (int t = 0; t < fragV1.num_elements; ++t) fragV1.x[t] = wmma::__float_to_tf32(fragV1.x[t]);
        #pragma unroll
        for (int t = 0; t < NT; ++t) {
            wmma::fragment<wmma::matrix_b, 16, 16, 8, wmma::precision::tf32, wmma::row_major> fragA;
            wmma::load_matrix_sync(fragA, Ab + (long)k0 * san + c0 + t * 16, san);
            #pragma unroll
            for (int e = 0; e < fragA.num_elements; ++e) fragA.x[e] = wmma::__float_to_tf32(fragA.x[e]);
            wmma::mma_sync(acc[0][t], fragV0, fragA, acc[0][t]);
            wmma::mma_sync(acc[1][t], fragV1, fragA, acc[1][t]);
        }
    }

    // stage W (BLK, BNc) to per-warp smem, then YT = T^T @ W (small, lane-parallel).
    extern __shared__ float smem_cw[];
    float* sW = smem_cw + warp * (BLK * BNc);
    #pragma unroll
    for (int t = 0; t < NT; ++t) {
        wmma::store_matrix_sync(sW + 0       + t * 16, acc[0][t], BNc, wmma::mem_row_major);
        wmma::store_matrix_sync(sW + 16 * BNc + t * 16, acc[1][t], BNc, wmma::mem_row_major);
    }
    __syncwarp();
    // YT[i,c] = sum_k T[k,i] * W[k,c]. BLK*BNc outputs, 32 lanes.
    for (int idx = lane; idx < BLK * BNc; idx += 32) {
        int i = idx / BNc, c = idx % BNc;
        float a = 0.0f;
        #pragma unroll
        for (int k = 0; k < BLK; ++k) a += Tb[(long)k * stk + (long)i * stn] * sW[k * BNc + c];
        if (c0 + c < ncols) YTb[(long)i * syk + (long)c * syn] = a;
    }
}

extern "C" __global__ void qr_cobatch_w_4_16(
    const float* A, const float* V, const float* T, float* YT,
    int B,int N,int j,int pheight,int ncols,int jb,
    long sab,long san,long svb,long svk,long svn,long stb,long stk,long stn,long syb,long syk,long syn){
    cobatch_w_impl<4,16>(A,V,T,YT,B,N,j,pheight,ncols,jb,sab,san,svb,svk,svn,stb,stk,stn,syb,syk,syn);
}
