// ---------------------------------------------------------------------------
// qr_cobatch_wp: PIPELINED co-batched W-reduction. Same co-batch (warp-per-
// matrix, MB matrices/block) but the deep-K load chain is software-pipelined
// through cp.async double-buffered shared memory -> the per-k global-load
// latency is overlapped with the MMA of the previous chunk. Diagnosis (ncu):
// the un-pipelined co-batch raised occupancy 18%->47% but eligible-warps DROPPED
// 0.74->0.55 because every warp stalls on its serial load_matrix_sync->mma
// chain. cp.async staging breaks that chain (the Triton fused kernel's
// num_stages pipeline is exactly what made it win). KC=16 K-rows staged/chunk.
// ---------------------------------------------------------------------------
template<int MB, int BNc, int NBUF>
__device__ __forceinline__ void cobatch_wp_impl(
    const float* __restrict__ A, const float* __restrict__ V,
    const float* __restrict__ T, float* __restrict__ YT,
    int B, int N, int j, int pheight, int ncols, int jb,
    long sab, long san, long svb, long svk, long svn,
    long stb, long stk, long stn, long syb, long syk, long syn)
{
    const int warp = threadIdx.x >> 5;
    const int lane = threadIdx.x & 31;
    const int col_tile = blockIdx.x;
    const int mid = blockIdx.y * MB + warp;
    const int c0 = col_tile * BNc;
    const int BLK = 32;
    const int KC = 16;                       // K-rows staged per chunk
    const int NT = BNc / 16;                 // # of 16-wide N subtiles
    const bool live = (mid < B);

    const float* Ab = A + (long)mid * sab + (long)j * san + jb;   // (pheight, ncols)
    const float* Vb = V + (long)mid * svb;                        // (BLK, pheight)

    // Per-warp smem tiles, double-buffered. Layout per buffer per warp:
    //   sV: KC rows of V laid out (BLK x KC) row-major  -> 32*KC floats
    //   sA: (KC x BNc) row-major                         -> KC*BNc floats
    extern __shared__ float smem_wp[];
    const int VTILE = BLK * KC;              // 32*16 = 512
    const int ATILE = KC * BNc;              // 16*BNc
    const int PERW  = VTILE + ATILE;
    float* myV[NBUF];
    float* myA[NBUF];
    #pragma unroll
    for (int s = 0; s < NBUF; ++s) {
        float* buf = smem_wp + (long)s * (MB * PERW) + (long)warp * PERW;
        myV[s] = buf;
        myA[s] = buf + VTILE;
    }

    const int nchunks = (pheight + KC - 1) / KC;

    // --- stage one K-chunk into smem buffer `s` via cp.async (per-warp, 32 lanes).
    auto stage = [&](int s, int kc) {
        if (!live) return;
        int k0 = kc * KC;
        // V: want sV[blk*KC + r] = Vb[blk*svk + (k0+r)*svn], r in [0,KC). svn==1.
        //   each lane loads (BLK*KC)/32 = 16 elements; iterate.
        #pragma unroll
        for (int e = lane; e < VTILE; e += 32) {
            int blk = e / KC, r = e % KC;
            int kk = k0 + r;
            const float* gp = (kk < pheight) ? (Vb + (long)blk * svk + (long)kk * svn) : nullptr;
            if (gp) __pipeline_memcpy_async(&myV[s][blk * KC + r], gp, sizeof(float));
            else myV[s][blk * KC + r] = 0.0f;
        }
        // A: want sA[r*BNc + c] = Ab[(k0+r)*san + c0 + c], c in [0,BNc).
        #pragma unroll
        for (int e = lane; e < ATILE; e += 32) {
            int r = e / BNc, c = e % BNc;
            int kk = k0 + r;
            bool ok = (kk < pheight) && (c0 + c < ncols);
            const float* gp = ok ? (Ab + (long)kk * san + c0 + c) : nullptr;
            if (gp) __pipeline_memcpy_async(&myA[s][r * BNc + c], gp, sizeof(float));
            else myA[s][r * BNc + c] = 0.0f;
        }
        __pipeline_commit();
    };

    wmma::fragment<wmma::accumulator, 16, 16, 8, float> acc[2][BNc / 16];
    #pragma unroll
    for (int m = 0; m < 2; ++m)
        #pragma unroll
        for (int t = 0; t < NT; ++t) wmma::fill_fragment(acc[m][t], 0.0f);

    // prime the pipeline
    int nstage = nchunks < NBUF ? nchunks : NBUF;
    for (int s = 0; s < nstage; ++s) stage(s, s);

    for (int kc = 0; kc < nchunks; ++kc) {
        int s = kc % NBUF;
        __pipeline_wait_prior(NBUF - 1);     // wait until chunk `kc`'s buffer ready
        __syncwarp();
        // MMA from smem: KC=16 -> two wmma K=8 steps.
        #pragma unroll
        for (int kk = 0; kk < KC; kk += 8) {
            wmma::fragment<wmma::matrix_a, 16, 16, 8, wmma::precision::tf32, wmma::row_major> fV0, fV1;
            wmma::load_matrix_sync(fV0, myV[s] + 0  * KC + kk, KC);
            wmma::load_matrix_sync(fV1, myV[s] + 16 * KC + kk, KC);
            #pragma unroll
            for (int t = 0; t < fV0.num_elements; ++t) fV0.x[t] = wmma::__float_to_tf32(fV0.x[t]);
            #pragma unroll
            for (int t = 0; t < fV1.num_elements; ++t) fV1.x[t] = wmma::__float_to_tf32(fV1.x[t]);
            #pragma unroll
            for (int t = 0; t < NT; ++t) {
                wmma::fragment<wmma::matrix_b, 16, 16, 8, wmma::precision::tf32, wmma::row_major> fA;
                wmma::load_matrix_sync(fA, myA[s] + (long)kk * BNc + t * 16, BNc);
                #pragma unroll
                for (int e = 0; e < fA.num_elements; ++e) fA.x[e] = wmma::__float_to_tf32(fA.x[e]);
                wmma::mma_sync(acc[0][t], fV0, fA, acc[0][t]);
                wmma::mma_sync(acc[1][t], fV1, fA, acc[1][t]);
            }
        }
        __syncwarp();
        int nxt = kc + NBUF;
        if (nxt < nchunks) stage(s, nxt);
    }

    if (!live) return;
    float* Tb = T + (long)mid * stb;
    float* YTb = YT + (long)mid * syb + (long)c0 * syn;
    // reuse buffer 0's region as W staging (pipeline done)
    float* sW = smem_wp + (long)warp * (BLK * BNc);
    __syncwarp();
    #pragma unroll
    for (int t = 0; t < NT; ++t) {
        wmma::store_matrix_sync(sW + 0       + t * 16, acc[0][t], BNc, wmma::mem_row_major);
        wmma::store_matrix_sync(sW + 16 * BNc + t * 16, acc[1][t], BNc, wmma::mem_row_major);
    }
    __syncwarp();
    for (int idx = lane; idx < BLK * BNc; idx += 32) {
        int i = idx / BNc, c = idx % BNc;
        float a = 0.0f;
        #pragma unroll
        for (int k = 0; k < BLK; ++k) a += Tb[(long)k * stk + (long)i * stn] * sW[k * BNc + c];
        if (c0 + c < ncols) YTb[(long)i * syk + (long)c * syn] = a;
    }
}

